func (s *ManualCommitStrategy) CondenseAndMarkFullyCondensed(ctx context.Context, sessionID string) error {
	logCtx := logging.WithComponent(ctx, "checkpoint")

	repo, err := OpenRepository(ctx)
	if err != nil {
		logging.Warn(logCtx, "eager condense: failed to open repository",
			slog.String("session_id", sessionID),
			slog.String("error", err.Error()),
		)
		return nil // fail-open
	}
	defer repo.Close()

	var shadowBranchName string
	var didCondense bool
	mutErr := MutateSessionState(ctx, sessionID, func(state *SessionState) error {
		// Only ENDED sessions are eligible. The detached session-end child can
		// lose a race with a same-ID resume (ENDED → IDLE/ACTIVE revival is a
		// legal transition), and condensing a revived session would wipe its
		// in-flight prompt attribution, reset the checkpoint window mid-turn,
		// and leave a stale FullyCondensed=true that makes PostCommit skip the
		// session's next end. Re-checking under the state lock closes that
		// window for every caller.
		if state.Phase != session.PhaseEnded {
			logging.Info(logCtx, "eager condense: session no longer ended, skipping",
				slog.String("session_id", sessionID),
				slog.String("phase", string(state.Phase)),
			)
			return ErrMutationSkip
		}

		// Sessions with FilesTouched must be processed by PostCommit for
		// carry-forward tracking — each user commit that overlaps with
		// tracked files gets its own checkpoint. Eagerly condensing here
		// would prevent that 1:1 linkage.
		if len(state.FilesTouched) > 0 {
			return ErrMutationSkip
		}

		if state.StepCount <= 0 {
			state.FullyCondensed = true
			return nil
		}

		shadowBranchName = getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
		refName := plumbing.NewBranchReferenceName(shadowBranchName)
		_, refErr := repo.Reference(refName, true)
		hasShadowBranch := refErr == nil

		if !hasShadowBranch {
			logging.Info(logCtx, "eager condense: no shadow branch",
				slog.String("session_id", sessionID),
				slog.String("shadow_branch", shadowBranchName),
			)
			state.StepCount = 0
			state.FullyCondensed = true
			return nil
		}

		// Mint the checkpoint ID only now that condensation is actually going to
		// run — the skip paths above (files-touched, no steps, no shadow branch)
		// return before this, so a no-op session stop no longer pays the ID mint
		// (and its checkpoints-config load).
		checkpointID, genErr := cpkg.GenerateCheckpointID(logCtx)
		if genErr != nil {
			logging.Warn(logCtx, "eager condense: failed to generate checkpoint ID",
				slog.String("error", genErr.Error()),
			)
			return ErrMutationSkip // fail-open; PostCommit retries
		}

		result, condErr := s.CondenseSession(ctx, repo, checkpointID, state, nil)
		if condErr != nil {
			logging.Warn(logCtx, "eager condense on session stop failed, PostCommit will retry",
				slog.String("session_id", sessionID),
				slog.String("error", condErr.Error()),
			)
			return ErrMutationSkip // fail-open
		}

		if result.Skipped {
			logging.Info(logCtx, "eager condense skipped (no transcript or files), marking fully condensed",
				slog.String("session_id", sessionID),
			)
			state.FullyCondensed = true
			return nil
		}

		resetCheckpointWindow(state)
		state.CheckpointTranscriptStart = result.TotalTranscriptLines
		state.LastCheckpointID = checkpointID
		state.LastCheckpointCommitHash = state.BaseCommit
		state.RealignAttributionBase(state.BaseCommit)
		state.PromptAttributions = nil
		state.PendingPromptAttribution = nil
		state.FullyCondensed = true
		// Phase stays ENDED — do NOT set to IDLE

		logging.Info(logCtx, "eager condense on session stop succeeded",
			slog.String("session_id", sessionID),
			slog.String("checkpoint_id", result.CheckpointID.String()),
		)
		didCondense = true
		return nil
	})
	if errors.Is(mutErr, ErrStateNotFound) {
		return nil
	}
	if mutErr != nil {
		return fmt.Errorf("failed to save session state: %w", mutErr)
	}

	if didCondense && shadowBranchName != "" {
		if err := s.cleanupShadowBranchIfUnused(ctx, repo, shadowBranchName, sessionID); err != nil {
			logging.Warn(logCtx, "eager condense: failed to clean up shadow branch",
				slog.String("shadow_branch", shadowBranchName),
				slog.String("error", err.Error()),
			)
		}
	}
	return nil
}

// cleanupShadowBranchIfUnused deletes a shadow branch if no other active sessions reference it.
func (s *ManualCommitStrategy) cleanupShadowBranchIfUnused(ctx context.Context, _ *git.Repository, shadowBranchName, excludeSessionID string) error {
	// List all session states to check if any other session uses this shadow branch
	allStates, err := s.listAllSessionStates(ctx)
	if err != nil {
		return fmt.Errorf("failed to list session states: %w", err)
	}

	for _, state := range allStates {
		if state.SessionID == excludeSessionID {
			continue
		}
		otherShadow := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
		if otherShadow == shadowBranchName && state.StepCount > 0 {
			// Another session still needs this shadow branch
			return nil
		}
	}

	// No other sessions need it, delete the shadow branch via CLI
	// (go-git v5's RemoveReference doesn't persist with packed refs/worktrees)
	if err := DeleteBranchCLI(ctx, shadowBranchName); err != nil {
		// Branch already gone is not an error
		if errors.Is(err, ErrBranchNotFound) {
			return nil
		}
		return fmt.Errorf("failed to remove shadow branch: %w", err)
	}
	return nil
}

package execx

import (
	"context"
	"fmt"
	"io"
	"os"
	"os/exec"
	"testing"
)

// SpawnDetached re-execs the current executable as a detached, fire-and-forget
// child running args, surviving the parent's exit (new session on Unix,
// CREATE_NEW_PROCESS_GROUP | DETACHED_PROCESS on Windows, via detachFromTTY).
// The child runs in dir (os.TempDir() when empty, so the child never holds the
// parent's working directory), inherits the parent's environment, and has its
// stdout/stderr discarded. Best-effort: the spawn is advisory background work
// and the returned error exists only so callers can log that the child never
// started (e.g. the running executable was deleted out from under us) — the
// parent is the last process with working logging, so discarding it leaves no
// evidence at all.
//
// In-process `go test` runs are a no-op: the current executable is the test
// binary, and re-execing it would fork the whole suite. Tests exercise the
// call sites through their spawn seams instead.
func SpawnDetached(dir string, args ...string) error {
	if testing.Testing() {
		return nil
	}
	executable, err := os.Executable()
	if err != nil {
		return fmt.Errorf("resolve current executable: %w", err)
	}

	// context.Background(): the child must outlive the parent, so it is never
	// tied to a cancellable context.
	cmd := exec.CommandContext(context.Background(), executable, args...)
	detachFromTTY(cmd)
	cmd.Dir = dir
	if cmd.Dir == "" {
		cmd.Dir = os.TempDir()
	}
	cmd.Env = os.Environ()
	cmd.Stdout = io.Discard
	cmd.Stderr = io.Discard

	if err := cmd.Start(); err != nil {
		return fmt.Errorf("start detached child (%v): %w", args, err)
	}
	// Release the process so it can run independently of the parent.
	//nolint:errcheck // best effort — the child continues regardless
	_ = cmd.Process.Release()
	return nil
}

