135		parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
136		parseHookType(rawHooks, "PreToolUse", &preToolUse)
137		parseHookType(rawHooks, "PostToolUse", &postToolUse)
138	
139		// If force is true, remove all existing Entire hooks first
140		if force {
141			sessionStart = removeEntireHooks(sessionStart)
142			sessionEnd = removeEntireHooks(sessionEnd)
143			stop = removeEntireHooks(stop)
144			userPromptSubmit = removeEntireHooks(userPromptSubmit)
145			preToolUse = removeEntireHooksFromMatchers(preToolUse)
146			postToolUse = removeEntireHooksFromMatchers(postToolUse)
147		}
148	
149		// Define hook commands
150		var sessionStartCmd, sessionEndCmd, stopCmd, userPromptSubmitCmd, preTaskCmd, postTaskCmd, postTodoCmd string
151		if localDev {
152			sessionStartCmd = localDevHookCommand(HookNameSessionStart)
153			sessionEndCmd = localDevHookCommand(HookNameSessionEnd)
154			stopCmd = localDevHookCommand(HookNameStop)
155			userPromptSubmitCmd = localDevHookCommand(HookNameUserPromptSubmit)
156			preTaskCmd = localDevHookCommand(HookNamePreTask)
157			postTaskCmd = localDevHookCommand(HookNamePostTask)
158			postTodoCmd = localDevHookCommand(HookNamePostTodo)
159		} else {
160			sessionStartCmd = agent.WrapProductionJSONWarningHookCommand("entire hooks claude-code session-start", agent.WarningFormatMultiLine)
161			sessionEndCmd = agent.WrapProductionSilentHookCommand("entire hooks claude-code session-end")
162			stopCmd = agent.WrapProductionSilentHookCommand("entire hooks claude-code stop")
163			userPromptSubmitCmd = agent.WrapProductionSilentHookCommand("entire hooks claude-code user-prompt-submit")
164			preTaskCmd = agent.WrapProductionSilentHookCommand("entire hooks claude-code pre-task")
165			postTaskCmd = agent.WrapProductionSilentHookCommand("entire hooks claude-code post-task")
166			postTodoCmd = agent.WrapProductionSilentHookCommand("entire hooks claude-code post-todo")
167		}
168	
169		count := 0
170	
171		// Add hooks if they don't exist
172		if !hookCommandExists(sessionStart, sessionStartCmd) {
173			sessionStart = addHookToMatcher(sessionStart, "", sessionStartCmd)
174			count++
175		}
176		if !hookCommandExists(sessionEnd, sessionEndCmd) {
177			sessionEnd = addHookToMatcher(sessionEnd, "", sessionEndCmd)
178			count++
179		}
180		if !hookCommandExists(stop, stopCmd) {
181			stop = addHookToMatcher(stop, "", stopCmd)
182			count++
183		}
184		if !hookCommandExists(userPromptSubmit, userPromptSubmitCmd) {
185			userPromptSubmit = addHookToMatcher(userPromptSubmit, "", userPromptSubmitCmd)
186			count++
187		}
188		if !hookCommandExistsWithMatcher(preToolUse, subagentToolMatcher, preTaskCmd) {
189			preToolUse = addHookToMatcher(preToolUse, subagentToolMatcher, preTaskCmd)
190			count++
191		}
192		if !hookCommandExistsWithMatcher(postToolUse, subagentToolMatcher, postTaskCmd) {
193			postToolUse = addHookToMatcher(postToolUse, subagentToolMatcher, postTaskCmd)
194			count++
195		}
196		if !hookCommandExistsWithMatcher(postToolUse, taskToolMatcher, postTodoCmd) {
197			postToolUse = addHookToMatcher(postToolUse, taskToolMatcher, postTodoCmd)
198			count++
199		}
200	
201		// Add permissions.deny rule if not present
202		permissionsChanged := false
203		var denyRules []string
204		if denyRaw, ok := rawPermissions["deny"]; ok {
205			if err := json.Unmarshal(denyRaw, &denyRules); err != nil {
206				return 0, fmt.Errorf("failed to parse permissions.deny in settings.json: %w", err)
207			}
208		}
209		if !slices.Contains(denyRules, metadataDenyRule) {
210			denyRules = append(denyRules, metadataDenyRule)
211			denyJSON, err := json.Marshal(denyRules)
212			if err != nil {
213				return 0, fmt.Errorf("failed to marshal permissions.deny: %w", err)
214			}
215			rawPermissions["deny"] = denyJSON
216			permissionsChanged = true
217		}
218	
219		if count == 0 && !permissionsChanged {
220			return 0, nil // All hooks and permissions already installed
221		}
222	
223		// Marshal modified hook types back to rawHooks
224		marshalHookType(rawHooks, "SessionStart", sessionStart)
225		marshalHookType(rawHooks, "SessionEnd", sessionEnd)
226		marshalHookType(rawHooks, "Stop", stop)
227		marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
228		marshalHookType(rawHooks, "PreToolUse", preToolUse)
229		marshalHookType(rawHooks, "PostToolUse", postToolUse)
230	
231		// Marshal hooks and update raw settings
232		hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawHooks)
233		if err != nil {
234			return 0, fmt.Errorf("failed to marshal hooks: %w", err)
235		}
236		rawSettings["hooks"] = hooksJSON
237	
238		// Marshal permissions and update raw settings
239		permJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawPermissions)
240		if err != nil {
241			return 0, fmt.Errorf("failed to marshal permissions: %w", err)
242		}
243		rawSettings["permissions"] = permJSON
244	
245		// Write back to file
246		if err := os.MkdirAll(filepath.Dir(settingsPath), 0o750); err != nil {
247			return 0, fmt.Errorf("failed to create .claude directory: %w", err)
248		}
249	
250		output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
251		if err != nil {
252			return 0, fmt.Errorf("failed to marshal settings: %w", err)
253		}
254	
255		if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
256			return 0, fmt.Errorf("failed to write settings.json: %w", err)
257		}
258	
259		return count, nil
260	}
261	
262	// parseHookType parses a specific hook type from rawHooks into the target slice.
263	// Silently ignores parse errors (leaves target unchanged).
264	func parseHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]ClaudeHookMatcher) {
265		if data, ok := rawHooks[hookType]; ok {
266			//nolint:errcheck,gosec // Intentionally ignoring parse errors - leave target as nil/empty
267			json.Unmarshal(data, target)
268		}
269	}
270	
271	// marshalHookType marshals a hook type back to rawHooks.
272	// If the slice is empty, removes the key from rawHooks.
273	func marshalHookType(rawHooks map[string]json.RawMessage, hookType string, matchers []ClaudeHookMatcher) {
274		if len(matchers) == 0 {
275			delete(rawHooks, hookType)
276			return
277		}
278		data, err := jsonutil.MarshalWithNoHTMLEscape(matchers)
279		if err != nil {
280			return // Silently ignore marshal errors (shouldn't happen)
281		}
282		rawHooks[hookType] = data
283	}
284	
285	// UninstallHooks removes Entire hooks from Claude Code settings.
286	func (c *ClaudeCodeAgent) UninstallHooks(ctx context.Context) error {
287		// Use repo root to find .claude directory when run from a subdirectory
288		repoRoot, err := paths.WorktreeRoot(ctx)
289		if err != nil {
290			repoRoot = "." // Fallback to CWD if not in a git repo
291		}
292		settingsPath := filepath.Join(repoRoot, ".claude", ClaudeSettingsFileName)
293		data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
294		if err != nil {
295			return nil //nolint:nilerr // No settings file means nothing to uninstall
296		}
297	
298		var rawSettings map[string]json.RawMessage
299		if err := json.Unmarshal(data, &rawSettings); err != nil {
300			return fmt.Errorf("failed to parse settings.json: %w", err)
301		}
302	
303		// rawHooks preserves unknown hook types (e.g., "Notification", "SubagentStop")
304		var rawHooks map[string]json.RawMessage
305		if hooksRaw, ok := rawSettings["hooks"]; ok {
306			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
307				return fmt.Errorf("failed to parse hooks: %w", err)
308			}
309		}
310		if rawHooks == nil {
311			rawHooks = make(map[string]json.RawMessage)
312		}
313	
314		// Parse only the hook types we need to modify
315		var sessionStart, sessionEnd, stop, userPromptSubmit, preToolUse, postToolUse []ClaudeHookMatcher
316		parseHookType(rawHooks, "SessionStart", &sessionStart)
317		parseHookType(rawHooks, "SessionEnd", &sessionEnd)
318		parseHookType(rawHooks, "Stop", &stop)
319		parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
320		parseHookType(rawHooks, "PreToolUse", &preToolUse)
321		parseHookType(rawHooks, "PostToolUse", &postToolUse)
322	
323		// Remove Entire hooks from all hook types
324		sessionStart = removeEntireHooks(sessionStart)
325		sessionEnd = removeEntireHooks(sessionEnd)
326		stop = removeEntireHooks(stop)
327		userPromptSubmit = removeEntireHooks(userPromptSubmit)
328		preToolUse = removeEntireHooksFromMatchers(preToolUse)
329		postToolUse = removeEntireHooksFromMatchers(postToolUse)
330	
331		// Marshal modified hook types back to rawHooks
332		marshalHookType(rawHooks, "SessionStart", sessionStart)
333		marshalHookType(rawHooks, "SessionEnd", sessionEnd)
334		marshalHookType(rawHooks, "Stop", stop)
335		marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
336		marshalHookType(rawHooks, "PreToolUse", preToolUse)
337		marshalHookType(rawHooks, "PostToolUse", postToolUse)
338	
339		// Also remove the metadata deny rule from permissions
340		var rawPermissions map[string]json.RawMessage
341		if permRaw, ok := rawSettings["permissions"]; ok {
342			if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
343				// If parsing fails, just skip permissions cleanup
344				rawPermissions = nil
345			}
346		}
347	
348		if rawPermissions != nil {
349			if denyRaw, ok := rawPermissions["deny"]; ok {
350				var denyRules []string
351				if err := json.Unmarshal(denyRaw, &denyRules); err == nil {
352					// Filter out the metadata deny rule
353					filteredRules := make([]string, 0, len(denyRules))
354					for _, rule := range denyRules {
355						if rule != metadataDenyRule {
356							filteredRules = append(filteredRules, rule)
357						}
358					}
359					if len(filteredRules) > 0 {
360						denyJSON, err := json.Marshal(filteredRules)
361						if err == nil {
362							rawPermissions["deny"] = denyJSON
363						}
364					} else {
365						// Remove empty deny array
366						delete(rawPermissions, "deny")
367					}
368				}
369			}
370	
371			// If permissions is empty, remove it entirely
372			if len(rawPermissions) > 0 {
373				permJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawPermissions)
374				if err == nil {
375					rawSettings["permissions"] = permJSON
376				}
377			} else {
378				delete(rawSettings, "permissions")
379			}
380		}
381	
382		// Marshal hooks back (preserving unknown hook types)
383		if len(rawHooks) > 0 {
384			hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(rawHooks)
385			if err != nil {
386				return fmt.Errorf("failed to marshal hooks: %w", err)
387			}
388			rawSettings["hooks"] = hooksJSON
389		} else {
390			delete(rawSettings, "hooks")
391		}
392	
393		// Write back
394		output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
395		if err != nil {
396			return fmt.Errorf("failed to marshal settings: %w", err)
397		}
398		if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
399			return fmt.Errorf("failed to write settings.json: %w", err)
400		}
401		return nil
402	}
403	
404	// loadClaudeSettings reads and parses .claude/settings.json from the repo root.
405	// Returns ok=false when the file is missing or unparseable.
406	func loadClaudeSettings(ctx context.Context) (ClaudeSettings, bool) {
407		// Use repo root to find .claude directory when run from a subdirectory
408		repoRoot, err := paths.WorktreeRoot(ctx)
409		if err != nil {
410			repoRoot = "." // Fallback to CWD if not in a git repo
411		}
412		settingsPath := filepath.Join(repoRoot, ".claude", ClaudeSettingsFileName)
413		data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
414		if err != nil {
415			return ClaudeSettings{}, false
416		}
417	
418		var settings ClaudeSettings
419		if err := json.Unmarshal(data, &settings); err != nil {
420			return ClaudeSettings{}, false
421		}
422		return settings, true
423	}
424	
425	// AreHooksInstalled checks if Entire hooks are installed.
426	func (c *ClaudeCodeAgent) AreHooksInstalled(ctx context.Context) bool {
427		settings, ok := loadClaudeSettings(ctx)
428		if !ok {
429			return false
430		}
431		// Check for at least one of our hooks (new, wrapped, or legacy format)
432		return hasEntireHook(settings.Hooks.Stop)
433	}
434	
435	// HookConfigState describes how Entire's Claude Code hooks compare to what
436	// InstallHooks would write today.
437	type HookConfigState int
438	
439	const (
440		// HooksAbsent means Entire hooks are not installed in this repo.
441		HooksAbsent HookConfigState = iota
442		// HooksCurrent means the installed hooks match the current config.
443		HooksCurrent
444		// HooksOutdated means Entire hooks are installed but the current tool-use
445		// matchers no longer carry them (e.g. an older CLI wrote them under the now
446		// non-firing "Task"/"TodoWrite" matchers). Fix: `entire enable --force`.
447		HooksOutdated
448	)
449	
450	// CheckHookConfig reports whether Entire's Claude Code hooks are absent,
451	// current, or outdated. It is a read-only diagnostic used by `entire status`
452	// and `entire doctor`; it never modifies settings. Outdated is detected on the
453	// positive spec: Entire is installed (Stop hook present) yet one of the current
454	// tool-use matchers does not carry its Entire hook.
455	func CheckHookConfig(ctx context.Context) HookConfigState {
456		settings, ok := loadClaudeSettings(ctx)
457		if !ok || !hasEntireHook(settings.Hooks.Stop) {
458			return HooksAbsent
459		}
460		subagentTools := splitMatcherTools(subagentToolMatcher)
461		taskTools := splitMatcherTools(taskToolMatcher)
462		if !hasEntireHookCoveringTools(settings.Hooks.PreToolUse, subagentTools) ||
463			!hasEntireHookCoveringTools(settings.Hooks.PostToolUse, subagentTools) ||
464			!hasEntireHookCoveringTools(settings.Hooks.PostToolUse, taskTools) {
465			return HooksOutdated
466		}
467		return HooksCurrent
468	}
469	
470	// Helper functions for hook management
471	
472	func hookCommandExists(matchers []ClaudeHookMatcher, command string) bool {
473		for _, matcher := range matchers {
474			for _, hook := range matcher.Hooks {
475				if hook.Command == command {
476					return true
477				}
478			}
479		}
480		return false
481	}
482	
483	func hasEntireHook(matchers []ClaudeHookMatcher) bool {
484		for _, matcher := range matchers {
485			for _, hook := range matcher.Hooks {
486				if isEntireHook(hook.Command) {
487					return true
488				}
489			}
490		}
491		return false
492	}
493	
494	// splitMatcherTools splits a Claude Code tool matcher into its exact tool
495	// names. Matchers that InstallHooks writes are `|`-separated lists (Claude Code
496	// also accepts `,`); whitespace around separators is ignored. Returns the tools
497	// in order, dropping empties.
498	func splitMatcherTools(matcher string) []string {
499		parts := strings.FieldsFunc(matcher, func(r rune) bool { return r == '|' || r == ',' })
500		tools := make([]string, 0, len(parts))
501		for _, p := range parts {
502			if t := strings.TrimSpace(p); t != "" {
503				tools = append(tools, t)
504			}
505		}
506		return tools
507	}
508	
509	// hasEntireHookCoveringTools reports whether an Entire hook is installed under a
510	// matcher that covers every tool in want. A widened matcher still counts: a
511	// matcher of "TaskCreate|TaskUpdate|TaskGet" covers {TaskCreate, TaskUpdate},
512	// so users who broaden a matcher aren't falsely flagged as outdated.
513	func hasEntireHookCoveringTools(matchers []ClaudeHookMatcher, want []string) bool {
514		for _, matcher := range matchers {
515			have := splitMatcherTools(matcher.Matcher)
516			coversAll := true
517			for _, w := range want {
518				if !slices.Contains(have, w) {
519					coversAll = false
520					break
521				}
522			}
523			if !coversAll {
524				continue
525			}
526			for _, hook := range matcher.Hooks {
527				if isEntireHook(hook.Command) {
528					return true
529				}
530			}
531		}
532		return false
533	}
534	
535	func hookCommandExistsWithMatcher(matchers []ClaudeHookMatcher, matcherName, command string) bool {
536		for _, matcher := range matchers {
537			if matcher.Matcher == matcherName {
538				for _, hook := range matcher.Hooks {
539					if hook.Command == command {
540						return true
541					}
542				}
543			}
544		}
545		return false
546	}
547	
548	func addHookToMatcher(matchers []ClaudeHookMatcher, matcherName, command string) []ClaudeHookMatcher {
549		entry := ClaudeHookEntry{
550			Type:    "command",
551			Command: command,
552		}
553	
554		// If no matcher name, add to a matcher with empty string
555		if matcherName == "" {
556			for i, matcher := range matchers {
557				if matcher.Matcher == "" {
558					matchers[i].Hooks = append(matchers[i].Hooks, entry)
559					return matchers
560				}
561			}
562			return append(matchers, ClaudeHookMatcher{
563				Matcher: "",
564				Hooks:   []ClaudeHookEntry{entry},
565			})
566		}
567	
568		// Find or create matcher with the given name
569		for i, matcher := range matchers {
570			if matcher.Matcher == matcherName {
571				matchers[i].Hooks = append(matchers[i].Hooks, entry)
572				return matchers
573			}
574		}
575	
576		return append(matchers, ClaudeHookMatcher{
577			Matcher: matcherName,
578			Hooks:   []ClaudeHookEntry{entry},
579		})
580	}
581	
582	// isEntireHook checks if a command is an Entire hook (old or new format)
583	func isEntireHook(command string) bool {
584		return agent.IsManagedHookCommand(command, entireHookPrefixes)
585	}
586	
587	// removeEntireHooks removes all Entire hooks from a list of matchers (for simple hooks like Stop)
588	func removeEntireHooks(matchers []ClaudeHookMatcher) []ClaudeHookMatcher {
589		result := make([]ClaudeHookMatcher, 0, len(matchers))
590		for _, matcher := range matchers {
591			filteredHooks := make([]ClaudeHookEntry, 0, len(matcher.Hooks))
592			for _, hook := range matcher.Hooks {
593				if !isEntireHook(hook.Command) {
594					filteredHooks = append(filteredHooks, hook)
595				}
596			}
597			// Only keep the matcher if it has hooks remaining
598			if len(filteredHooks) > 0 {
599				matcher.Hooks = filteredHooks
600				result = append(result, matcher)
601			}
602		}
603		return result
604	}
605	
606	// removeEntireHooksFromMatchers removes Entire hooks from tool-use matchers (PreToolUse, PostToolUse)
607	// This handles the nested structure where hooks are grouped by tool matcher (e.g., "Agent", "TaskCreate|TaskUpdate")
608	func removeEntireHooksFromMatchers(matchers []ClaudeHookMatcher) []ClaudeHookMatcher {
609		// Same logic as removeEntireHooks - both work on the same structure
610		return removeEntireHooks(matchers)
611	}
